{"implementation":"def solve(case):
    from fractions import Fraction
    import math

    if not isinstance(case, dict):
        raise TypeError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("case requires segments and budget")

    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list) or not segments:
        raise ValueError("segments must be a non-empty list")
    if isinstance(budget, bool) or not isinstance(budget, int):
        raise TypeError("budget must be an integer")

    names = []
    importances = []
    allocations = []
    capacities = []
    seen_names = set()

    for index, segment in enumerate(segments):
        if not isinstance(segment, dict):
            raise TypeError("each segment must be an object")
        required = ("name", "importance", "minimum", "capacity")
        if any(field not in segment for field in required):
            raise ValueError("each segment requires name, importance, minimum, and capacity")

        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]

        if not isinstance(name, str) or not name:
            raise ValueError("segment names must be non-empty strings")
        if name in seen_names:
            raise ValueError("segment names must be unique")
        if isinstance(importance, bool) or not isinstance(importance, (int, float)):
            raise TypeError("importance must be numeric")
        if not math.isfinite(importance) or importance < 0:
            raise ValueError("importance must be finite and non-negative")
        if isinstance(minimum, bool) or not isinstance(minimum, int):
            raise TypeError("minimum must be an integer")
        if isinstance(capacity, bool) or not isinstance(capacity, int):
            raise TypeError("capacity must be an integer")
        if minimum < 0 or capacity < minimum:
            raise ValueError("capacity must be at least the non-negative minimum")

        seen_names.add(name)
        names.append(name)
        importances.append(Fraction(str(importance)))
        allocations.append(minimum)
        capacities.append(capacity)

    minimum_total = sum(allocations)
    capacity_total = sum(capacities)
    if budget < minimum_total or budget > capacity_total:
        raise ValueError("budget must be between the quota sum and total capacity")

    remaining = budget - minimum_total
    while remaining:
        best_index = None
        best_priority = None
        for index in range(len(segments)):
            if allocations[index] >= capacities[index]:
                continue
            priority = importances[index] / (allocations[index] + 1)
            if best_index is None or priority > best_priority:
                best_index = index
                best_priority = priority
        if best_index is None:
            raise RuntimeError("unable to conserve the requested budget")
        allocations[best_index] += 1
        remaining -= 1

    allocation_by_name = {
        name: allocations[index] for index, name in enumerate(names)
    }
    return {
        "allocations": allocations,
        "allocation_by_name": allocation_by_name,
        "total": sum(allocations),
    }
